#[cfg(test)]
mod every_member {
    #![allow(clippy::unwrap_used, reason = "a test fails by panicking")]

    use super::*;

    #[test]
    fn every_member_reads_whole_and_comes_back() {
        for member in Gowri::ALL {
            assert_eq!(Gowri::from_key(member.key()), Some(member));
            assert_eq!(Gowri::from_id(member.id()), Some(member));
            assert_eq!(Gowri::try_from(member.key_id()), Ok(member));
            assert_eq!(member.full_key(), format!("{}.{}", Kind::Gowri.name(), member.key()));
            assert_eq!(member.full_key().parse::<Gowri>(), Ok(member));
            assert_eq!(member.to_string().parse::<Gowri>(), Ok(member));
            let json = serde_json::to_string(&member).unwrap();
            assert_eq!(serde_json::from_str::<Gowri>(&json).unwrap(), member);
            assert_eq!(<Gowri as Catalogued>::mark(member), member.mark());
            assert_ne!(member.doc(), "");
            assert_ne!(member.glyph(), Some(""));
            let _ = (member.deprecated(), member.sources(), member.unverified());
            assert_ne!(format!("{:?}", member.attributes()), "");
        }
        assert_eq!(Gowri::ALL.len(), Kind::Gowri.count());
    }
}
